'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major-string' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-complex128' );


// MAIN //

/**
* Solves one of the systems of equations `A*x = b` or `A^T*x = b` or `A^H*x = b`, where `b` and `x` are `N` element vectors and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix, supplied in packed form.
*
* @private
* @param {string} order - storage layout
* @param {string} uplo - specifies whether `A` is an upper or lower triangular matrix
* @param {string} trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param {string} diag - specifies whether `A` has a unit diagonal
* @param {NonNegativeInteger} N - number of elements along each dimension of `A`
* @param {Complex128Array} AP - packed form of a symmetric matrix `A`
* @param {integer} strideAP - `AP` stride length
* @param {NonNegativeInteger} offsetAP - starting index for `AP`
* @param {Complex128Array} x - input vector
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @returns {Complex128Array} `x`
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var AP = new Complex128Array( [ 1.0, 1.0, 2.0, 2.0, 4.0, 4.0, 3.0, 3.0, 5.0, 5.0, 6.0, 6.0 ] );
* var x = new Complex128Array( [ 0.0, 2.0, 0.0, 20.0, 0.0, 62.0 ] );
*
* ztpsv( 'row-major', 'lower', 'no-transpose', 'non-unit', 3, AP, 1, 0, x, 1, 0 );
* // x => <Complex128Array>[ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ]
*/
function ztpsv( order, uplo, trans, diag, N, AP, strideAP, offsetAP, x, strideX, offsetX ) { // eslint-disable-line max-params, max-len
	var nonunit;
	var viewAP;
	var viewX;
	var retmp;
	var imtmp;
	var magsq;
	var remul;
	var immul;
	var isrm;
	var sign;
	var rex;
	var imx;
	var rea;
	var ima;
	var iap;
	var ix0;
	var ix1;
	var sap;
	var kk;
	var ox;
	var sx;
	var i1;
	var i0;

	// Note on variable naming convention: sa#, ix#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	isrm = isRowMajor( order );
	nonunit = ( diag === 'non-unit' );

	// Reinterpret arrays as real-valued views of interleaved real and imaginary components:
	viewAP = reinterpret( AP, 0 );
	viewX = reinterpret( x, 0 );
	if ( trans === 'conjugate-transpose' ) {
		sign = -1;
	} else {
		sign = 1;
	}
	ox = offsetX * 2;
	kk = offsetAP * 2;
	sx = strideX * 2;
	sap = strideAP * 2;

	if (
		( !isrm && uplo === 'upper' && trans === 'no-transpose' ) ||
		( isrm && uplo === 'lower' && trans !== 'no-transpose' )
	) {
		ix1 = ox + ((N-1)*sx);
		kk += ((N*(N+1)/2)-1) * sap;
		for ( i1 = N - 1; i1 >= 0; i1-- ) {
			rex = viewX[ ix1 ];
			imx = viewX[ ix1+1 ];
			if ( rex !== 0.0 || imx !== 0.0 ) {
				iap = kk;
				if ( nonunit ) {
					rea = viewAP[ iap ];
					ima = sign * viewAP[ iap+1 ];
					magsq = (rea*rea) + (ima*ima);
					retmp = ((rex*rea) + (imx*ima)) / magsq;
					imtmp = ((imx*rea) - (rex*ima)) / magsq;
					viewX[ ix1 ] = retmp;
					viewX[ ix1+1 ] = imtmp;
				} else {
					retmp = rex;
					imtmp = imx;
				}
				ix0 = ix1 - sx;
				iap -= sap;
				for ( i0 = i1 - 1; i0 >= 0; i0-- ) {
					rea = viewAP[ iap ];
					ima = sign * viewAP[ iap+1 ];
					rex = viewX[ ix0 ];
					imx = viewX[ ix0+1 ];
					remul = (retmp*rea) - (imtmp*ima);
					immul = (retmp*ima) + (imtmp*rea);
					viewX[ ix0 ] = rex - remul;
					viewX[ ix0+1 ] = imx - immul;
					ix0 -= sx;
					iap -= sap;
				}
			}
			ix1 -= sx;
			kk -= (i1+1) * sap;
		}
		return x;
	}
	if (
		( !isrm && uplo === 'lower' && trans === 'no-transpose' ) ||
		( isrm && uplo === 'upper' && trans !== 'no-transpose' )
	) {
		ix1 = ox;
		for ( i1 = 0; i1 < N; i1++ ) {
			rex = viewX[ ix1 ];
			imx = viewX[ ix1+1 ];
			if ( rex !== 0.0 || imx !== 0.0 ) {
				iap = kk;
				if ( nonunit ) {
					rea = viewAP[ iap ];
					ima = sign * viewAP[ iap+1 ];
					magsq = (rea*rea) + (ima*ima);
					retmp = ((rex*rea) + (imx*ima)) / magsq;
					imtmp = ((imx*rea) - (rex*ima)) / magsq;
					viewX[ ix1 ] = retmp;
					viewX[ ix1+1 ] = imtmp;
				} else {
					retmp = rex;
					imtmp = imx;
				}
				ix0 = ix1 + sx;
				iap += sap;
				for ( i0 = i1 + 1; i0 < N; i0++ ) {
					rea = viewAP[ iap ];
					ima = sign * viewAP[ iap+1 ];
					rex = viewX[ ix0 ];
					imx = viewX[ ix0+1 ];
					remul = (retmp*rea) - (imtmp*ima);
					immul = (retmp*ima) + (imtmp*rea);
					viewX[ ix0 ] = rex - remul;
					viewX[ ix0+1 ] = imx - immul;
					ix0 += sx;
					iap += sap;
				}
			}
			ix1 += sx;
			kk += (N-i1) * sap;
		}
		return x;
	}
	if (
		( !isrm && uplo === 'upper' && trans !== 'no-transpose' ) ||
		( isrm && uplo === 'lower' && trans === 'no-transpose' )
	) {
		ix1 = ox;
		for ( i1 = 0; i1 < N; i1++ ) {
			rex = viewX[ ix1 ];
			imx = viewX[ ix1+1 ];
			retmp = rex;
			imtmp = imx;
			ix0 = ox;
			iap = kk;
			for ( i0 = 0; i0 < i1; i0++ ) {
				rea = viewAP[ iap ];
				ima = sign * viewAP[ iap+1 ];
				rex = viewX[ ix0 ];
				imx = viewX[ ix0+1 ];
				retmp -= (rex*rea) - (imx*ima);
				imtmp -= (rex*ima) + (imx*rea);
				ix0 += sx;
				iap += sap;
			}
			if ( nonunit ) {
				rea = viewAP[ iap ];
				ima = sign * viewAP[ iap+1 ];
				magsq = (rea*rea) + (ima*ima);
				remul = (retmp*rea) + (imtmp*ima);
				immul = (imtmp*rea) - (retmp*ima);
				retmp = remul / magsq;
				imtmp = immul / magsq;
			}
			viewX[ ix1 ] = retmp;
			viewX[ ix1+1 ] = imtmp;
			ix1 += sx;
			kk += (i1+1) * sap;
		}
		return x;
	}
	// ( !isrm && uplo === 'lower' && trans !== 'no-transpose' ) || ( isrm && uplo === 'upper' && trans === 'no-transpose' )
	ix1 = ox + ((N-1)*sx);
	kk += ((N*(N+1)/2)-1) * sap;
	for ( i1 = N - 1; i1 >= 0; i1-- ) {
		rex = viewX[ ix1 ];
		imx = viewX[ ix1+1 ];
		retmp = rex;
		imtmp = imx;
		ix0 = ox + ((N-1)*sx);
		iap = kk;
		for ( i0 = N - 1; i0 > i1; i0-- ) {
			rea = viewAP[ iap ];
			ima = sign * viewAP[ iap+1 ];
			rex = viewX[ ix0 ];
			imx = viewX[ ix0+1 ];
			retmp -= (rex*rea) - (imx*ima);
			imtmp -= (rex*ima) + (imx*rea);
			ix0 -= sx;
			iap -= sap;
		}
		if ( nonunit ) {
			rea = viewAP[ iap ];
			ima = sign * viewAP[ iap+1 ];
			magsq = (rea*rea) + (ima*ima);
			remul = (retmp*rea) + (imtmp*ima);
			immul = (imtmp*rea) - (retmp*ima);
			retmp = remul / magsq;
			imtmp = immul / magsq;
		}
		viewX[ ix1 ] = retmp;
		viewX[ ix1+1 ] = imtmp;
		ix1 -= sx;
		kk -= (N-i1) * sap;
	}
	return x;
}


// EXPORTS //

module.exports = ztpsv;
